CREATE TABLE IF NOT EXISTS api_tokens(id uuid PRIMARY KEY,site_id text REFERENCES sites(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id),token_hash text UNIQUE NOT NULL,scopes text[] NOT NULL,expires_at timestamptz,revoked boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY,site_id text REFERENCES sites(id) ON DELETE CASCADE,name text NOT NULL,dsl jsonb NOT NULL,created_by uuid,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notification_channels(id uuid PRIMARY KEY,site_id text REFERENCES sites(id) ON DELETE CASCADE,kind text NOT NULL,encrypted_config text NOT NULL);
CREATE TABLE IF NOT EXISTS report_schedules(id uuid PRIMARY KEY,site_id text REFERENCES sites(id) ON DELETE CASCADE,report_id uuid REFERENCES reports(id) ON DELETE CASCADE,channel_id uuid REFERENCES notification_channels(id) ON DELETE CASCADE,cadence text NOT NULL,next_at timestamptz NOT NULL,enabled boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS notification_jobs(id uuid PRIMARY KEY,site_id text NOT NULL,channel_id uuid,body jsonb NOT NULL,dedupe_key text UNIQUE NOT NULL,status text DEFAULT 'pending',attempts integer DEFAULT 0,next_at timestamptz DEFAULT now(),lease_until timestamptz,last_error text);
CREATE TABLE IF NOT EXISTS notification_logs(id bigserial PRIMARY KEY,job_id uuid,site_id text,success boolean,created_at timestamptz DEFAULT now(),error text);
CREATE TABLE IF NOT EXISTS share_links(id uuid PRIMARY KEY,site_id text REFERENCES sites(id) ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,password_hash text,expires_at timestamptz,revoked boolean DEFAULT false,frame_origins text[] NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS alert_rules(id uuid PRIMARY KEY,site_id text REFERENCES sites(id) ON DELETE CASCADE,kind text NOT NULL,config jsonb NOT NULL,channel_id uuid,next_at timestamptz DEFAULT now(),consecutive integer DEFAULT 0,silenced_until timestamptz,last_fired timestamptz);
CREATE TABLE IF NOT EXISTS site_invites(id uuid PRIMARY KEY,site_id text REFERENCES sites(id) ON DELETE CASCADE,email text NOT NULL,role text NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,accepted_at timestamptz);
CREATE TABLE IF NOT EXISTS export_jobs(id uuid PRIMARY KEY,site_id text REFERENCES sites(id) ON DELETE CASCADE,actor_id uuid,status text DEFAULT 'pending',format text NOT NULL,full_export boolean DEFAULT false,lease_until timestamptz,path text,error text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS replay_chunks(site_id text REFERENCES sites(id) ON DELETE CASCADE,session_id text,seq integer,payload jsonb NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(site_id,session_id,seq));
CREATE TABLE IF NOT EXISTS heatmap_points(site_id text REFERENCES sites(id) ON DELETE CASCADE,path text,kind text,x integer,y integer,viewport integer,count bigint DEFAULT 1,PRIMARY KEY(site_id,path,kind,x,y,viewport));
CREATE TABLE IF NOT EXISTS experiments(id uuid PRIMARY KEY,site_id text REFERENCES sites(id) ON DELETE CASCADE,name text,variants jsonb NOT NULL,goal text NOT NULL,enabled boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS experiment_assignments(experiment_id uuid REFERENCES experiments(id) ON DELETE CASCADE,visitor_id text,variant text,converted boolean DEFAULT false,PRIMARY KEY(experiment_id,visitor_id));
